function YearOverYearComparison({rows,country}){
 const comparison=useMemo(()=>{
  const relevant=rows.filter(r=>(country==='All countries'||r.country===country)&&r.month);
  const years=[...new Set(relevant.map(r=>fiscalYearStart(r.month)).filter(y=>y!==null))].sort((a,b)=>b-a);
  if(years.length<2)return {ready:false,reason:'At least two financial years are required for a year-over-year comparison.'};
  const currentYear=years[0],previousYear=currentYear-1;
  const byYearMonth=new Map();
  relevant.forEach(r=>{
   const fy=fiscalYearStart(r.month);if(fy!==currentYear&&fy!==previousYear)return;
   const month=Number(String(r.month).slice(5,7));if(month<1||month>12)return;
   const fiscalMonth=(month+8)%12,key=fy+'-'+fiscalMonth;
   const v=byYearMonth.get(key)||{revenue:0,qty:0,profit:0};
   v.revenue+=Number(r.revenue_inr||0);
   v.qty+=Number(r.shipped_qty||0);
   v.profit+=Number(r.profit_inr||0);
   byYearMonth.set(key,v);
  });
  const data=Array.from({length:12},(_,i)=>{
   const current=byYearMonth.get(currentYear+'-'+i),previous=byYearMonth.get(previousYear+'-'+i);
   return {index:i,month:['Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec','Jan','Feb','Mar'][i],current:current?.revenue??null,previous:previous?.revenue??null,currentQty:current?.qty??null,previousQty:previous?.qty??null};
  }).filter(d=>d.current!==null&&d.previous!==null);
  if(!data.length)return {ready:false,reason:'No matching months are available in both financial years.'};
  const current=data.reduce((s,d)=>s+d.current,0),previous=data.reduce((s,d)=>s+d.previous,0);
  const currentQty=data.reduce((s,d)=>s+d.currentQty,0),previousQty=data.reduce((s,d)=>s+d.previousQty,0);
  return {ready:true,currentYear,previousYear,data,current,previous,currentQty,previousQty,revenueChange:previous===0?null:(current-previous)/Math.abs(previous)*100,qtyChange:previousQty===0?null:(currentQty-previousQty)/Math.abs(previousQty)*100,country,months:data.length};
 },[rows,country]);
 const pct=v=>v===null?'N/A':(v>0?'+':'')+v.toFixed(1)+'%';
 const fy=y=>'FY '+y+'–'+String((y+1)%100).padStart(2,'0');
 return <section className="panel chart-panel yoy-panel"><div className="panel-top"><div><span className="panel-kicker">PHASE 2 · YEAR-OVER-YEAR ANALYTICS</span><h2>Current FY vs previous FY</h2><p>Revenue and shipped quantity compared across matching financial-year months{country!=='All countries'?' for '+country:''}.</p></div><div className="panel-icon"><TrendingUp size={20}/></div></div>{comparison.ready?<><div className="yoy-kpis"><div className="result-card"><span className="panel-kicker">{fy(comparison.currentYear)} REVENUE</span><strong>{inr(comparison.current)}</strong></div><div className="result-card"><span className="panel-kicker">{fy(comparison.previousYear)} REVENUE</span><strong>{inr(comparison.previous)}</strong></div><div className="result-card"><span className="panel-kicker">REVENUE GROWTH</span><strong className={comparison.revenueChange===null?'':comparison.revenueChange>=0?'positive':'negative'}>{pct(comparison.revenueChange)}</strong><p>{comparison.months} matched months</p></div><div className="result-card"><span className="panel-kicker">{fy(comparison.currentYear)} SHIPPED QTY</span><strong>{Number(comparison.currentQty).toLocaleString('en-IN',{maximumFractionDigits:1})}</strong></div><div className="result-card"><span className="panel-kicker">{fy(comparison.previousYear)} SHIPPED QTY</span><strong>{Number(comparison.previousQty).toLocaleString('en-IN',{maximumFractionDigits:1})}</strong></div><div className="result-card"><span className="panel-kicker">QUANTITY GROWTH</span><strong className={comparison.qtyChange===null?'':comparison.qtyChange>=0?'positive':'negative'}>{pct(comparison.qtyChange)}</strong><p>Based on shipped quantity</p></div></div><div className="chart-wrap yoy-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={comparison.data} margin={{top:10,right:10,left:0,bottom:0}}><CartesianGrid stroke="#253148" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="month" stroke="#71809c" tickLine={false} axisLine={false} fontSize={10}/><YAxis stroke="#71809c" tickLine={false} axisLine={false} fontSize={9} tickFormatter={v=>inr(v)}/><Tooltip contentStyle={{background:'#111a2d',border:'1px solid #303c55',borderRadius:12}} formatter={v=>inr(v)}/><Bar dataKey="previous" name={fy(comparison.previousYear)} fill="#8e9bff" radius={[4,4,0,0]}/><Bar dataKey="current" name={fy(comparison.currentYear)} fill="#65e0c4" radius={[4,4,0,0]}/></ComposedChart></ResponsiveContainer></div><div className="chart-wrap yoy-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={comparison.data} margin={{top:10,right:10,left:0,bottom:0}}><CartesianGrid stroke="#253148" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="month" stroke="#71809c" tickLine={false} axisLine={false} fontSize={10}/><YAxis stroke="#71809c" tickLine={false} axisLine={false} fontSize={9} tickFormatter={v=>Number(v).toLocaleString('en-IN')}/><Tooltip contentStyle={{background:'#111a2d',border:'1px solid #303c55',borderRadius:12}} formatter={v=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:1})}/><Bar dataKey="previousQty" name={fy(comparison.previousYear)+' shipped qty'} fill="#8e9bff" radius={[4,4,0,0]}/><Bar dataKey="currentQty" name={fy(comparison.currentYear)+' shipped qty'} fill="#65e0c4" radius={[4,4,0,0]}/></ComposedChart></ResponsiveContainer></div></>:<div className="yoy-empty"><Activity size={18}/><span>{comparison.reason} No comparison values are fabricated; import verified rows for both years to enable this analysis.</span></div>}</section>
}
